INSERT OR REPLACE INTO _counters (key, value) VALUES ('reservation', 100);
INSERT OR REPLACE INTO _counters (key, value) VALUES ('question', 100);

-- 2026-08 quality repair: merchant popularity and capacity are independent
-- business attributes, not row-number progressions.
UPDATE merchants
SET review_count = max(2, review_count + CASE (rowid % 17)
      WHEN 0 THEN 37 WHEN 1 THEN -11 WHEN 2 THEN 64 WHEN 3 THEN -28
      WHEN 4 THEN 9 WHEN 5 THEN 83 WHEN 6 THEN -19 WHEN 7 THEN 42
      WHEN 8 THEN -35 WHEN 9 THEN 56 WHEN 10 THEN 3 WHEN 11 THEN 71
      WHEN 12 THEN -14 WHEN 13 THEN 25 WHEN 14 THEN -47 WHEN 15 THEN 18 ELSE 49 END),
    max_party_size = max(1, max_party_size + CASE (rowid % 11)
      WHEN 0 THEN 2 WHEN 1 THEN -1 WHEN 2 THEN 5 WHEN 3 THEN -3
      WHEN 4 THEN 1 WHEN 5 THEN 7 WHEN 6 THEN -2 WHEN 7 THEN 4
      WHEN 8 THEN -4 WHEN 9 THEN 3 ELSE 0 END)
WHERE rowid > 6;

-- 2026-08 second-pass manual-cat repair: background merchants belong to
-- Hangzhou and carry categories that match their names; reviews are varied
-- first-hand observations rather than one generated visit/evidence/action frame.
UPDATE merchants SET name = replace(replace(replace(replace(replace(replace(replace(replace(name,
  '田林','文三'), '天山','湖墅'), '碧云','蒋村'), '五角场','转塘'),
  '龙华','良渚'), '曹家渡','彭埠'), '联洋','九堡'), '控江','闻堰')
WHERE merchant_id LIKE 'm_%';

DELETE FROM reviews WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM reservations WHERE datetime > '2026-07-06T09:10:00+08:00';
DELETE FROM merchant_qa WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM saved_merchants WHERE saved_at > '2026-07-06T09:10:00+08:00';

DELETE FROM reviews WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM reservations WHERE datetime > '2026-07-06T09:10:00+08:00';
DELETE FROM merchant_qa WHERE created_at > '2026-07-06T09:10:00+08:00';
DELETE FROM saved_merchants WHERE saved_at > '2026-07-06T09:10:00+08:00';

UPDATE merchants SET address = replace(replace(replace(replace(replace(replace(address,
  '桂林路','文一路'), '延安西路','延安路'), '国定路','古墩路'),
  '虹漕路','紫荆花路'), '愚园路','教工路'), '四平路','体育场路')
WHERE merchant_id LIKE 'm_%';

UPDATE merchants SET area = CASE (rowid % 7)
  WHEN 0 THEN '西湖' WHEN 1 THEN '上城' WHEN 2 THEN '拱墅' WHEN 3 THEN '滨江'
  WHEN 4 THEN '钱塘' WHEN 5 THEN '余杭' ELSE '萧山' END
WHERE merchant_id LIKE 'm_%';

UPDATE merchants
SET address = area || '区' || substr(address, instr(address,'区') + 1)
WHERE merchant_id LIKE 'm_%' AND instr(address,'区') > 0;

UPDATE merchants
SET name = replace(name,'运动评估门诊','运动评估工作室'),
    category = CASE
      WHEN name LIKE '%补给咖啡店%' THEN 'restaurant'
      WHEN name LIKE '%自行车维护点%' OR name LIKE '%基础装备店%' OR name LIKE '%运动评估门诊%' THEN 'home_service'
      ELSE 'venue' END
WHERE merchant_id LIKE 'm_%';

UPDATE reviews SET body = CASE (rowid % 40)
  WHEN 0 THEN '更衣区清洁，浅水泳道傍晚人少；周末九点后储物柜会紧张。'
  WHEN 1 THEN '前台解释取消规则很清楚，临时改期在小程序里就能完成。'
  WHEN 2 THEN '室内车阻力调节顺畅，但两台风扇噪声较大，靠窗位置更舒服。'
  WHEN 3 THEN '绿道入口标识醒目，桥下雨后容易积水，管理人员会提前放围挡。'
  WHEN 4 THEN '租赁车辆刹车和胎压都在取车时复核，头盔需要单独计费。'
  WHEN 5 THEN '工作日晚七点排队约十分钟，课程结束后淋浴区会短时拥挤。'
  WHEN 6 THEN '教练对新手动作讲得细，但体验结束后课程介绍时间偏长。'
  WHEN 7 THEN '公共交通方便，从地铁口步行约六分钟，停车位反而不多。'
  WHEN 8 THEN '页面价格和现场一致，没有强制购买套餐，水和毛巾需自备。'
  WHEN 9 THEN '周六上午器材维护及时，发现故障后工作人员马上停用了设备。'
  WHEN 10 THEN '泳池水温适中，深浅水区分隔明确，第一次来不容易走错。'
  WHEN 11 THEN '场馆通风一般，连续骑行半小时后体感偏闷，建议选靠门位置。'
  WHEN 12 THEN '预约时段保留十五分钟，迟到后需要等下一组空位。'
  WHEN 13 THEN '雨天从地库入口更方便，地面铺了防滑垫但坡道仍有积水。'
  WHEN 14 THEN '取消入口藏在订单详情里，找到后操作顺畅，退款次日到账。'
  WHEN 15 THEN '共享器材型号比较旧，不过工作人员每天会检查固定螺丝。'
  WHEN 16 THEN '早场照明均匀且安静，八点半以后团课音乐明显变大。'
  WHEN 17 THEN '休息区座位够用，饮水机在二楼，第一次到店要问前台。'
  WHEN 18 THEN '低价时段数量有限，页面不含教练服务，结算前要看清项目。'
  WHEN 19 THEN '场地面积不大，适合短时技术练习，不适合多人同时训练。'
  WHEN 20 THEN '工作人员没有代订或代付，同行人需要分别登记自己的信息。'
  WHEN 21 THEN '车辆尺码选择不多，身高较高的人最好提前问清车架库存。'
  WHEN 22 THEN '浅水区周日下午有亲子课，想安静练习可以改到午饭前。'
  WHEN 23 THEN '门店回复电话很快，押金、取车证件和逾时费用都说明了。'
  WHEN 24 THEN '照明在傍晚足够，闭馆前半小时部分区域会提前清洁。'
  WHEN 25 THEN '近期评价提到的风扇故障已经修好，这次使用没有再遇到。'
  WHEN 26 THEN '储物柜用临时密码，离场时会自动失效，不需要另交钥匙。'
  WHEN 27 THEN '前台能提供简单路线图，第一次骑封闭路线也容易找到出口。'
  WHEN 28 THEN '节假日前人流明显增加，现场排队约二十分钟，需预留入场时间。'
  WHEN 29 THEN '器材区地面干净，鞋底有水时工作人员会提醒先擦干。'
  WHEN 30 THEN '咖啡店座位不多，但可以装饮用水，补给价格与菜单一致。'
  WHEN 31 THEN '运动评估以动作观察为主，收费项会在开始前逐项说明。'
  WHEN 32 THEN '夜间店到九点仍开放，最后一小时只保留自助使用区域。'
  WHEN 33 THEN '社区活动中心有无障碍电梯，器材主要集中在三楼。'
  WHEN 34 THEN '装备店可以现场试戴手套，拆封类商品的退换限制写得明确。'
  WHEN 35 THEN '维护点检查了链条和刹车皮，报价确认后才开始更换零件。'
  WHEN 36 THEN '新手课人数控制得好，教练能逐个纠正姿势，没有赶进度。'
  WHEN 37 THEN '绿道施工信息更新及时，封闭路段当天没有看到骑行者进入。'
  WHEN 38 THEN '高峰期淋浴需要排队，前台建议先拉伸再去，更节省时间。'
  WHEN 39 THEN '场馆附近晚餐选择多，结束后步行五分钟就能到商业街。'
  ELSE body END
WHERE merchant_id LIKE 'm_%';

-- 2026-08 third-pass clone repair: each review is tied to the merchant actually
-- visited and uses ordinary varied review layouts.
UPDATE reviews
SET body = CASE (rowid % 7)
  WHEN 0 THEN (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || '：' || body
  WHEN 1 THEN '这次到 ' || (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || '，' || body
  WHEN 2 THEN body || ' 这是我在 ' || (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || ' 的实际体验。'
  WHEN 3 THEN '关于 ' || (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || '——' || body
  WHEN 4 THEN (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || '；' || body
  WHEN 5 THEN '在 ' || (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || ' 停留约半小时。' || body
  ELSE '朋友推荐了 ' || (SELECT name FROM merchants WHERE merchant_id=reviews.merchant_id) || '。' || body END
WHERE merchant_id LIKE 'm_%';
